(()=>{
 const grid=document.getElementById('collection-grid'),status=document.getElementById('collection-status'),empty=document.getElementById('collection-empty'),search=document.getElementById('collection-search'),sort=document.getElementById('collection-sort');
 const selected=new Set(),deleteButton=document.getElementById('collection-delete'),dialog=document.getElementById('delete-confirm');
 const updateSelection=()=>{deleteButton.disabled=!selected.size;deleteButton.textContent='선택 삭제 ('+selected.size+')';};
 deleteButton.addEventListener('click',()=>{const names=Craft.Library.list().filter(e=>selected.has(e.id)).map(e=>e.name);document.getElementById('delete-summary').textContent=names.length+'개 · '+names.join(', ');dialog.showModal();document.getElementById('delete-cancel').focus();});
 document.getElementById('delete-cancel').addEventListener('click',()=>dialog.close());
 document.getElementById('delete-accept').addEventListener('click',()=>{try{const count=Craft.Library.remove([...selected]);selected.clear();dialog.close();updateSelection();render();Craft.StorageCleanup?.collect();status.textContent=count+'개 무기를 삭제했어.';}catch(error){dialog.close();status.textContent=error.message;}});
 function render(){
  try{const entries=Craft.Library.list(),term=search.value.trim().toLocaleLowerCase(),shown=entries.filter(e=>e.name?.toLocaleLowerCase().includes(term));document.getElementById('collection-count').textContent=entries.length+' / 60';shown.sort(sort.value==='wins'?(a,b)=>(b.wins||0)-(a.wins||0):sort.value==='rarity'?(a,b)=>Craft.Rarity.get(b.rarity).rank-Craft.Rarity.get(a.rarity).rank:(a,b)=>b.createdAt-a.createdAt);grid.replaceChildren();empty.hidden=entries.length>0;status.textContent=entries.length?'무기 '+shown.length+'개 · 전적과 진화형이 이곳에 남아.':'';
   for(const entry of shown){const card=document.createElement('article');card.className='weapon-card';const image=document.createElement('img'),name=document.createElement('h2'),rarity=document.createElement('span'),types=document.createElement('div'),record=document.createElement('p'),link=document.createElement('a');image.className='weapon-card-art';image.alt=entry.name+'의 원본 그림';name.textContent=entry.name;const tier=Craft.Rarity.get(entry.rarity);rarity.className='collection-rarity';rarity.style.setProperty('--rarity-color',GamePalette.tokens[tier.color]);rarity.textContent=tier.label+(entry.evolution?' · '+entry.evolution+'차 진화':'');types.className='type-line';types.innerHTML=Craft.Types.badges(entry.types);record.textContent=(entry.battles||0)+'전 '+(entry.wins||0)+'승 · 최고 '+(entry.bestStage||0)+'관문';
    try{const saved=Craft.Library.resolve(entry.id),params=new URLSearchParams(saved.hash.slice(1));image.src=saved.image;params.set('journey',Craft.Journey.seed());params.set('stage','0');link.href='battle.html#'+params;link.textContent='꺼내 들고 새 원정';}catch(error){link.textContent='원본 저장 기록 확인 필요';record.textContent=error.message;}
    const epithet=document.createElement('p');epithet.className='weapon-epithet';epithet.textContent=Craft.Chronicle.tag(entry);epithet.hidden=!epithet.textContent;
    const journal=document.createElement('details'),summary=document.createElement('summary'),list=document.createElement('ol');journal.className='weapon-journal';summary.textContent='무기의 기록';journal.append(summary,list);const own=Craft.Chronicle.deeds(entry),legacy=Craft.Chronicle.inherited(entry),history=Craft.Chronicle.history(entry);
    for(const d of [...own,...legacy]){const li=document.createElement('li'),title=document.createElement('strong'),detail=document.createElement('span');title.textContent='「'+d.title+'」';detail.textContent=(legacy.includes(d)?'전신 '+d.weaponName+'의 기록 · ':'')+d.detail;li.append(title,detail);list.append(li);}
    for(const h of history){const li=document.createElement('li');li.textContent=(h.won?'승리':'패배')+' · '+h.enemy+' · '+h.turns+'턴 · 남은 체력 '+h.hp+(Number.isFinite(h.at)?' · '+new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric'}).format(h.at):'');list.append(li);}if(!own.length&&!legacy.length&&!history.length){const li=document.createElement('li');li.textContent='다음 전투부터 상대와 순간들이 여기에 남아.';list.append(li);}
    const choice=document.createElement('label'),checkbox=document.createElement('input'),caption=document.createElement('span');choice.className='weapon-select';checkbox.type='checkbox';checkbox.checked=selected.has(entry.id);checkbox.setAttribute('aria-label',entry.name+' 삭제 선택');caption.textContent='선택';checkbox.addEventListener('change',()=>{if(checkbox.checked)selected.add(entry.id);else selected.delete(entry.id);updateSelection();});choice.append(checkbox,caption);
    card.append(choice,image,rarity,name,epithet,types,record,journal,link);grid.append(card);
   }
   if(entries.length&&!shown.length)status.textContent='조건에 맞는 무기가 없어. 검색어를 확인해 봐.';
  }catch(error){status.textContent=error.message;empty.hidden=true;}
 }
 search.addEventListener('input',render);sort.addEventListener('change',render);render();try{Craft.StorageCleanup?.collect();}catch(error){status.textContent=error.message;}
})();
